import{_ as a,o as n,c as i,ai as l}from"./chunks/framework.Ba-VnP44.js";const u=JSON.parse('{"title":"数据与安全规范","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/03-quality/data-security.md","filePath":"ai/productivity/dev-spec/03-quality/data-security.md"}'),e={name:"ai/productivity/dev-spec/03-quality/data-security.md"};function p(r,s,t,d,c,h){return n(),i("div",null,[...s[0]||(s[0]=[l(`<h1 id="数据与安全规范" tabindex="-1">数据与安全规范 <a class="header-anchor" href="#数据与安全规范" aria-label="Permalink to “数据与安全规范”">​</a></h1><blockquote><p>第三层 · 质量保障。解决「怎么保护项目资产和数据」——敏感信息、破坏性操作、输入与权限、依赖风险，从项目准备到交付全程检查。</p></blockquote><h2 id="贯穿全流程的定位" tabindex="-1">贯穿全流程的定位 <a class="header-anchor" href="#贯穿全流程的定位" aria-label="Permalink to “贯穿全流程的定位”">​</a></h2><p>数据安全不是上线前才查。它在各阶段的关注点：</p><table tabindex="0"><thead><tr><th>阶段</th><th>关注点</th></tr></thead><tbody><tr><td>项目准备</td><td>标记生产资源、敏感目录、禁改区</td></tr><tr><td>架构</td><td>数据迁移、权限模型、敏感字段设计</td></tr><tr><td>开发</td><td>不写死密钥、不打印隐私、外部入参校验</td></tr><tr><td>修复 / 重构</td><td>保护已有数据，改动可回滚</td></tr><tr><td>交付</td><td>全项安全检查，命中红线先停</td></tr></tbody></table><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to “核心内容”">​</a></h2><h3 id="敏感信息" tabindex="-1">敏感信息 <a class="header-anchor" href="#敏感信息" aria-label="Permalink to “敏感信息”">​</a></h3><ul><li>密钥、令牌、密码、手机号、身份证号不写进代码、配置、日志、提交信息。</li><li><code>.env</code>、凭证文件不进版本库；提供示例文件而非真实值。</li><li>日志不打印完整请求体、用户隐私、认证头。</li><li>提交前过一遍密钥扫描脚本。</li></ul><h3 id="破坏性操作" tabindex="-1">破坏性操作 <a class="header-anchor" href="#破坏性操作" aria-label="Permalink to “破坏性操作”">​</a></h3><p>以下操作命中即停，需人确认：</p><ul><li>删除数据、清库、改生产配置、不可逆迁移。</li><li>脚本里写死生产地址或高权限账号。</li><li>覆盖用户已有改动、强推、删除分支。</li><li>批量删除文件、批量格式化无关目录。</li></ul><p><strong>能只读就不写，能连测试库就不连生产库，能限定目录就不开放整个文件系统。</strong></p><h3 id="输入与权限" tabindex="-1">输入与权限 <a class="header-anchor" href="#输入与权限" aria-label="Permalink to “输入与权限”">​</a></h3><ul><li>外部入参校验：类型、长度、格式、范围。</li><li>越权访问拦截：数据范围、租户隔离、角色权限。</li><li>文件上传、路径拼接、SQL 拼接、命令拼接的风险检查。</li><li>幂等与重复执行：接口重试、消息重复消费不产生错误数据。</li></ul><h3 id="依赖与供应链" tabindex="-1">依赖与供应链 <a class="header-anchor" href="#依赖与供应链" aria-label="Permalink to “依赖与供应链”">​</a></h3><ul><li>不新增来源不明的依赖或脚本。</li><li>依赖版本锁定，不随意升级框架。</li><li>新增核心依赖需方案确认。</li></ul><h2 id="检查清单模板" tabindex="-1">检查清单模板 <a class="header-anchor" href="#检查清单模板" aria-label="Permalink to “检查清单模板”">​</a></h2><div class="language-markdown line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 安全检查（每次交付前）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 项 | 结论 | 说明 |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| -- | ---- | ---- |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 敏感信息 | 已检查 / 未检查 / 不适用 | |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 破坏性操作 | 已检查 / 未检查 / 不适用 | |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 输入校验 | 已检查 / 未检查 / 不适用 | |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 权限与数据隔离 | 已检查 / 未检查 / 不适用 | |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 依赖变更 | 无 / 有（已确认） | |</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">命中红线：&lt;逐条列出，或「无」&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h2 id="可复制提示词" tabindex="-1">可复制提示词 <a class="header-anchor" href="#可复制提示词" aria-label="Permalink to “可复制提示词”">​</a></h2><details><summary><strong>交付前安全检查</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请对本次改动做安全自查，只输出检查结果，不修改文件。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>改动：&lt;粘贴 diff&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>按四块检查：</span></span>
<span class="line"><span>1. 敏感信息：是否写入密钥、令牌、密码、隐私数据；是否打印完整请求体；凭证文件是否被跟踪。</span></span>
<span class="line"><span>2. 破坏性操作：是否有删数据、清库、改生产配置、不可逆迁移；是否写死生产地址或高权限账号。</span></span>
<span class="line"><span>3. 输入与权限：外部入参是否校验；越权和数据范围是否拦截；路径/SQL/命令拼接是否安全；是否考虑幂等。</span></span>
<span class="line"><span>4. 依赖与供应链：是否新增未知依赖或脚本，版本是否锁定。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每项给「已检查 / 未检查 / 不适用」和依据。命中红线的单独列出并标「需人确认」。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div></details><details><summary><strong>权限与数据范围自查</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请针对本次功能做权限与数据范围自查，本轮只分析，不改代码。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>功能描述：&lt;粘贴&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请检查：</span></span>
<span class="line"><span>1. 谁能访问这个功能，是否有越权风险。</span></span>
<span class="line"><span>2. 查询和写入是否带了必要的数据隔离条件（租户、用户、组织）。</span></span>
<span class="line"><span>3. 直接调用接口（绕过前端）能否看到不该看的数据。</span></span>
<span class="line"><span>4. 关键操作是否有二次校验。</span></span>
<span class="line"><span>5. 重复提交或重复消费会发生什么。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每条给「风险 → 触发条件 → 建议」。没问题的项写「已检查，无问题」。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div></details><h2 id="验收要点" tabindex="-1">验收要点 <a class="header-anchor" href="#验收要点" aria-label="Permalink to “验收要点”">​</a></h2><ul><li>[ ] 敏感信息、破坏性操作、输入权限、依赖四项都有明确结论。</li><li>[ ] 没有密钥、隐私数据进入代码或日志。</li><li>[ ] 破坏性操作都有人确认，没有写死生产资源。</li><li>[ ] 外部入参校验、越权拦截、幂等处理到位。</li></ul><p>Git 层面的资产保护见 <a href="/my-vitepress-site/ai/productivity/dev-spec/03-quality/git-version.html">Git 与版本管理</a>。</p>`,24)])])}const o=a(e,[["render",p]]);export{u as __pageData,o as default};
